const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function videoSource(value){try{const u=new URL(value);if(u.protocol!=='https:'||u.username||u.password)return null;const host=u.hostname.toLowerCase(),youtube=['youtube.com','www.youtube.com','m.youtube.com','youtube-nocookie.com','www.youtube-nocookie.com'].includes(host);let id='';if(host==='youtu.be')id=u.pathname.split('/')[1];else if(youtube){if(u.pathname==='/watch')id=u.searchParams.get('v')||'';else if(/^\/(embed|shorts|live)\//.test(u.pathname))id=u.pathname.split('/')[2]}if(id&&/^[A-Za-z0-9_-]{11}$/.test(id))return {type:'youtube',id};if(host==='youtu.be'||youtube)return null;return /\.(mp4|webm)$/i.test(u.pathname)?{type:'file',url:u.href}:null}catch{return null}}
function validVideo(value){return !!videoSource(value)}
function normalizeStored(key,value,fallback){const record=v=>v&&typeof v==='object'&&!Array.isArray(v);if(key==='demo-achievements')return value===true;if(key==='course-completions')return record(value)?Object.fromEntries(Object.entries(value).filter(([id,v])=>/^[a-z]+$/.test(id)&&Number.isFinite(v)&&v>0)):fallback;if(key==='daily-done')return record(value)?Object.fromEntries(Object.entries(value).filter(([k,v])=>/^\d{4}-\d{2}-\d{2}$/.test(k)&&v===true)):fallback;if(key==='assistant-draft'||key.startsWith('daily-code-'))return typeof value==='string'?value:fallback;if(key==='assistant-history')return Array.isArray(value)?value.filter(m=>record(m)&&['user','assistant'].includes(m.role)&&typeof m.id==='string'&&typeof m.text==='string'&&m.text.length<=30000&&typeof m.course==='string'&&Number.isFinite(m.time)):fallback;if(key==='portfolio'||key==='portfolio-trash'){const clean=p=>record(p)&&typeof p.id==='string'&&typeof p.title==='string'&&p.title.length<=100&&typeof p.description==='string'&&p.description.length<=1500&&typeof p.language==='string'&&typeof p.url==='string'&&(!p.url||safeProjectURL(p.url))&&(!p.image||typeof p.image==='string'&&/^data:image\/(jpeg|png|webp);base64,[A-Za-z0-9+/=]+$/.test(p.image));return key==='portfolio'?(Array.isArray(value)?value.filter(clean):fallback):(clean(value)?value:fallback);}if(key==='enrolled')return Array.isArray(value)?[...new Set(value.filter(v=>typeof v==='string'&&/^[a-z]+$/.test(v)))]:fallback;if(key==='notes')return Array.isArray(value)?value.filter(v=>record(v)&&typeof v.text==='string'&&v.text.length<=4000&&Number.isFinite(v.time)):fallback;if(key==='profile'){if(!record(value))return fallback;return {name:typeof value.name==='string'?value.name.slice(0,100):'',about:typeof value.about==='string'?value.about.slice(0,1000):'',avatar:typeof value.avatar==='string'&&/^data:image\/(jpeg|png|webp);base64,[A-Za-z0-9+/=]+$/.test(value.avatar)?value.avatar:''}}if(key==='courses'){if(!record(value))return fallback;const clean={};for(const [id,c]of Object.entries(value)){if(/^[a-z]+$/.test(id)&&record(c)&&typeof c.description==='string'&&c.description.trim()&&c.description.length<=500&&Array.isArray(c.topics)&&c.topics.length===6&&c.topics.every(t=>typeof t==='string'&&t.trim()&&t.length<=150))clean[id]={description:c.description,topics:c.topics}}return clean}if(key==='done'||key==='videos'){if(!record(value))return fallback;return Object.fromEntries(Object.entries(value).filter(([id,v])=>/^[a-z]+-[0-5]$/.test(id)&&(key==='done'?v===true:typeof v==='string'&&validVideo(v))))}if(key.startsWith('code-')||key.startsWith('lesson-note-'))return typeof value==='string'?value:fallback;return value}
function storageKey(k){const shared=['courses','videos','theme'];if(shared.includes(k))return 'school-'+k;const a=window.SchoolAccount?.state;if(a?.enabled){const scope=!a.ready?'pending':a.user?.id||'guest';return 'school-user-'+scope+'-'+k;}return 'school-'+k;}
const store={get(k,d){if(k==='profile'&&window.SchoolAccount?.state.enabled&&window.SchoolAccount.state.user)return window.SchoolAccount.state.profile||d;try{const value=JSON.parse(localStorage.getItem(storageKey(k)));return value===null?d:normalizeStored(k,value,d)}catch{return d}},set(k,v){return this.batch([[k,v]])},batch(entries){if(window.SchoolAccount?.state.enabled&&!window.SchoolAccount.state.ready){toast('Дождись подключения аккаунта и повтори действие.');return false;}const previous=[];try{for(const [k]of entries)previous.push([k,localStorage.getItem(storageKey(k))]);for(const [k,v]of entries)localStorage.setItem(storageKey(k),JSON.stringify(v));return true}catch{for(const [k,v]of previous){try{if(v===null)localStorage.removeItem(storageKey(k));else localStorage.setItem(storageKey(k),v)}catch{}}toast('Не удалось сохранить. Проверь свободное место в браузере.');return false}}};
