function catalog(){return `<h2>Выбери свой язык</h2><p class="lead">От первой строки до собственного проекта. Начни с направления, которое тебе интересно.</p><div class="catalog-tools"><input class="search" id="search" type="search" aria-label="Поиск направления" placeholder="Найти язык или технологию"><div class="filters" aria-label="Фильтр направлений">${[['all','Все'],['web','Веб'],['backend','Бэкенд'],['data','Данные'],['mobile','Мобильные'],['systems','Системные']].map(([id,n])=>`<button class="filter ${id==='all'?'active':''}" data-filter="${id}" aria-pressed="${id==='all'}">${n}</button>`).join('')}</div></div><div id="course-grid" class="course-grid"></div><p class="muted" id="catalog-count" aria-live="polite"></p><div class="center"><button class="button secondary" id="show-all">Смотреть все направления ↓</button></div>`}
function bindCatalog(){let expanded=view==='catalog',filter='all';function draw(){const term=$('#search').value.trim().toLowerCase(),found=courses.filter(c=>(filter==='all'||c.group===filter)&&(c.name+' '+c.description).toLowerCase().includes(term));const shown=expanded||term||filter!=='all'?found:found.slice(0,10);$('#course-grid').innerHTML=shown.map(card).join('')||'<p class="empty">Ничего не найдено. Попробуй другое название.</p>';$('#catalog-count').textContent=`Показано ${shown.length} из ${found.length} направлений` ;$('#show-all').hidden=expanded||!!term||filter!=='all'||found.length<=10}$('#search').oninput=draw;document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',x===b)});draw()});$('#show-all').onclick=()=>{expanded=true;draw()};draw()}
function home(){return `<div class="container"><section class="hero"><div><div class="eyebrow">МЕСТО, ГДЕ НАЧИНАЕТСЯ ТВОЙ КОД</div><h1>Думай логично.<br><span>Создавай смело.</span></h1><p>Программирование через практику: разбирайся в языке, пиши код и собирай собственные проекты.</p><div class="actions"><a class="button" href="#catalog">Выбрать направление ↗</a><a class="button secondary" href="${url('learn','javascript')}">Попробовать урок</a></div></div><div class="sculpture" aria-label="Объёмный металлический символ программирования"><div class="solid"><div class="slab back"></div><div class="slab"></div></div><span class="coordinate">LOGIC / PRACTICE / DEVELOPMENT</span></div></section><div class="strip"><span><b>Теория</b> без перегруза</span><span><b>Практика</b> в браузере</span><span><b>Свой темп</b> обучения</span><span><b>Код</b> с первой встречи</span></div><section class="block" id="catalog">${catalog()}</section>${pathwaysSection()}<section class="block learning-tools"><h2>Практика становится привычкой</h2><p class="lead">Сохраняй свои решения, собирай работы и возвращайся к вопросам, которые хочется разобрать.</p><div class="learning-tool-grid"><a href="${url('daily')}"><span class="tag">ПРАКТИКА</span><h3>Задание дня</h3><p>Небольшая задача с проверкой вывода и историей решённых дней.</p><span>Попробовать →</span></a><a href="${url('portfolio')}"><span class="tag">РЕЗУЛЬТАТ</span><h3>Моё портфолио</h3><p>Работы, скриншоты и технологии. Собирай результат обучения в одном месте.</p><span>Добавить работу →</span></a><a href="${url('assistant')}"><span class="tag">ПОДДЕРЖКА</span><h3>Помощник</h3><p>Отдельный чат для вопросов по коду. Подключение ИИ готовится.</p><span>Открыть чат →</span></a></div></section><section class="block approach" id="approach"><div><h2>Знания становятся<br>навыком в деле.</h2><p class="lead">В одной мастерской собраны материал урока, задание и редактор. Меньше переключений, больше внимания к задаче.</p><a class="button secondary" href="${url('learn','javascript')}">Зайти в мастерскую ↗</a></div><div class="steps"><article><b>↗</b><div><h3>Разберись в идее</h3><p>Прочитай объяснение и изучи пример. Видео появятся после добавления материалов преподавателем.</p></div></article><article><b>⌘</b><div><h3>Проверь на практике</h3><p>Измени код и посмотри результат. Учебные примеры JavaScript и HTML работают прямо здесь.</p></div></article><article><b>✓</b><div><h3>Продолжи со своего места</h3><p>Черновики и пройденные задания сохраняются в текущем браузере.</p></div></article></div></section>${projectSection()}${homeFaq()}<div class="cta"><div><h2>Первая строка проще,<br>чем кажется.</h2><p>Попробуй открытый учебный пример без регистрации.</p></div><a class="button" href="${url('learn','javascript')}">Написать первый код ↗</a></div></div>`}
function coursePage(){const g=LEARNING[course.group],joined=store.get('enrolled',[]).includes(course.id);return `<div class="container page"><a class="crumb" href="${url('catalog')}">← Все направления</a><div class="split course-intro"><div><span class="tag">${groupNames[course.group]} / Знакомство с направлением</span><h1 class="page-title">${esc(course.name)}.<br>Понимать и создавать.</h1><p class="lead">${esc(course.description)} ${g.audience}</p><div class="actions"><a class="button" href="${url('learn',course.id)}">Начать практику ↗</a><a class="button secondary" href="#program">Смотреть программу ↓</a></div></div><aside class="course-object panel"><div class="language-symbol">${esc(course.symbol)}</div><h3>${esc(course.name)} в твоём темпе</h3><div class="spec-row"><span>Точка входа</span><b>Основы языка</b></div><div class="spec-row"><span>Формат</span><b>Материал + практика</b></div><div class="spec-row"><span>Прогресс</span><b>На устройстве</b></div><button class="button secondary" id="enroll">${joined?'Убрать из моих направлений':'Добавить в мои направления'}</button><p class="muted" id="enroll-status" aria-live="polite"></p></aside></div><nav class="section-nav" aria-label="Разделы направления"><a href="#outcome">Результат</a><a href="#program">Программа</a><a href="#project">Проект</a><a href="#course-faq">Вопросы</a></nav><section class="block" id="outcome"><h2>Что станет понятнее</h2><p class="lead">${g.result}</p><div class="skill-grid">${g.skills.map((t,i)=>`<article><span class="skill-index">${String(i+1).padStart(2,'0')}</span><h3>${t}</h3><p>Отработай навык на небольшом примере, проверь результат и объясни решение своими словами.</p></article>`).join('')}</div></section><section class="block program-section" id="program"><h2>От первых понятий к проекту</h2><p class="lead">Предварительный маршрут знакомства с ${esc(course.name)}. Программу авторского курса преподаватель сможет уточнить.</p>${course.topics.map((t,i)=>`<details class="module" ${i===0?'open':''}><summary><span><small>ТЕМА ${i+1}</small>${esc(t)}</span><span>+</span></summary><p>${esc(lessonContent(i).theory)}</p><div class="module-practice"><b>Практика</b><p>${esc(lessonContent(i).task)}</p></div><a class="button secondary small" href="${url('learn',course.id,i)}">Перейти к теме ↗</a></details>`).join('')}</section><section class="block project-feature" id="project"><div class="project-art" aria-hidden="true"><span>{</span><strong>${esc(course.symbol)}</strong><span>}</span></div><div><span class="tag">ИДЕЯ ДЛЯ ПОРТФОЛИО</span><h2>${g.project}</h2><p class="lead">${g.projectText}</p><p class="muted">Это предложение учебного проекта, а не обещание состава авторского курса. Преподаватель сможет заменить его своей задачей.</p><a href="${url('projects')}" class="button secondary">Другие идеи проектов ↗</a></div></section><section class="block" id="course-faq"><h2>Перед первым уроком</h2>${faqItems([['Нужно ли уже уметь программировать?',g.audience+' Для начала достаточно уверенно пользоваться браузером и внимательно выполнять небольшие задания.'],['Что установить на компьютер?','Для открытых примеров достаточно браузера. Для полноценной разработки приложение или среду выбирают под язык и платформу. Мобильные интерфейсы и крупные проекты лучше собирать на компьютере.'],['Как работает запуск кода?',runtimeExplanation(course.id)],['Где стоимость и расписание?','Эти сведения ещё не предоставлены преподавателем. Пока можно изучить направление и попробовать открытую мастерскую.']])}</section></div>`}

