function lessonContent(i=lesson){const originalTopic=raw.find(c=>c[0]===course.id)[5].split('|')[i];const entry=course.topics[i]===originalTopic?LESSON_TEXT[course.id]?.[i]:null;if(entry)return {title:entry[0],theory:entry[1],task:entry[2],code:entry[3]};return {title:course.topics[i],theory:`Тема «${course.topics[i]}» входит в основы ${course.name}. Начни с запуска небольшой программы, затем измени одно значение и проследи, как это повлияло на результат. Сравни ожидаемый и фактический вывод. Полный материал по этой теме преподаватель добавит в редакторе курса.`,task:'Запусти стартовый пример. Измени сообщение и выполни программу повторно. Запиши, что изменилось в результате.'}}
function runtimeExplanation(id){return ['javascript','html'].includes(id)?'Этот пример запускается в браузере. JavaScript работает в отдельном потоке с лимитом времени. HTML/CSS отображаются в изолированном предпросмотре без выполнения скриптов. Для DOM-примеров нужна полноценная HTML-страница.':'У этого языка свой интерпретатор или компилятор. Вместо установки на устройство можно открыть встроенную среду OneCompiler. Она передаёт код своему серверу и возвращает результат. Нужен интернет; доступность и ограничения зависят от сервиса.'}
function sample(){return lessonContent().code||(course.id==='html'?htmlSample:LANGUAGE_START[course.id]||'')}
function learnPage(){const done=store.get('done',{}),data=lessonContent(),native=['javascript','html'].includes(course.id);return `<div class="container page classroom"><a class="crumb" href="${url('course',course.id)}">← ${esc(course.name)} / Обзор направления</a><div class="classroom-heading"><div><span class="tag">ТЕМА ${lesson+1} ИЗ ${course.topics.length}</span><h1>${esc(course.topics[lesson])}</h1></div><details class="lesson-picker"><summary>Содержание курса ⌄</summary><aside class="lesson-list"><h3>${esc(course.name)}</h3>${course.topics.map((t,i)=>`<a href="${url('learn',course.id,i)}" class="${lesson===i?'active':''}"><b>${done[course.id+'-'+i]?'✓':String(i+1).padStart(2,'0')}</b>${esc(t)}</a>`).join('')}</aside></details></div><div class="mobile-workspace-tabs" role="tablist" aria-label="Панели урока"><button role="tab" aria-selected="true" aria-controls="lesson-material" id="material-tab" data-workspace="material">Материал</button><button role="tab" aria-selected="false" aria-controls="lesson-editor" id="editor-tab" data-workspace="editor">Код и результат</button></div><div class="workspace" data-panel="material"><section class="lesson-material" id="lesson-material" aria-labelledby="material-tab"><div class="material-tabs" role="tablist" aria-label="Материалы урока"><button role="tab" id="theory-tab" aria-selected="true" aria-controls="theory-panel" data-material="theory">Теория</button><button role="tab" id="video-tab" aria-selected="false" aria-controls="video-panel" data-material="video">Видеоурок</button><button role="tab" id="notes-tab" aria-selected="false" aria-controls="notes-panel" data-material="notes">Мои заметки</button></div><div id="theory-panel" role="tabpanel" aria-labelledby="theory-tab" class="reading"><h2>${esc(data.title)}</h2><p>${esc(data.theory)}</p><div class="task-card"><span class="tag">ПРАКТИЧЕСКОЕ ЗАДАНИЕ</span><h3>Попробуй самостоятельно</h3><p id="task">${esc(data.task)}</p></div><details class="hint"><summary>Подсказка <span>+</span></summary><p>Сначала запусти исходный пример. Меняй по одному фрагменту, чтобы понимать причину каждого изменения. Если появилась ошибка, начни с её первой строки.</p></details><details class="hint"><summary>Как проверить себя <span>+</span></summary><p>${native?'Сравни вывод с условием и нажми «Проверить задание». Проверка относится только к этому небольшому примеру.':'Сравни вывод с условием. Для этого направления автоматическая оценка пока не подключена. Отметка завершения означает твою самостоятельную проверку.'}</p></details><p class="muted">${runtimeExplanation(course.id)}</p></div><div id="video-panel" role="tabpanel" aria-labelledby="video-tab" hidden><div class="video-slot" id="video-slot"><span class="play" aria-hidden="true">▷</span><strong>Здесь будет видеоурок</strong><p>Преподаватель сможет добавить видео к этой теме. Сейчас можно пройти материал и выполнить задание.</p><a class="button secondary small" href="${url('admin',course.id,lesson)}">Добавить видео ↗</a></div></div><div id="notes-panel" role="tabpanel" aria-labelledby="notes-tab" class="reading" hidden><h2>Мысли по ходу урока</h2><p>Запиши непонятные моменты, идеи и вопросы преподавателю. Заметка останется в этом браузере.</p><label>Моя заметка<textarea id="lesson-note" rows="12" placeholder="Что стоит повторить?">${esc(store.get('lesson-note-'+course.id+'-'+lesson,''))}</textarea></label><p class="muted" id="note-status" aria-live="polite">Сохраняется автоматически.</p></div></section><section class="lesson-editor" id="lesson-editor" aria-labelledby="editor-tab"><div class="editor"><div class="editor-bar"><span>${esc(course.name)} / ${native?'локальная среда':'черновик'}</span><button class="button small" id="run">${native?'Запустить ▷':'Открыть компилятор ↗'}</button></div><label class="sr-only" for="code">Редактор кода ${esc(course.name)}</label><textarea id="code" aria-label="Редактор кода ${esc(course.name)}" spellcheck="false" autocapitalize="off" autocomplete="off">${esc(store.get('code-'+course.id+'-'+lesson,sample()))}</textarea><div class="output-heading"><span>Результат</span><button id="clear-output">Очистить</button></div><div class="output" id="output" role="status">${native?'Запусти код, чтобы увидеть результат.':'Код можно редактировать прямо здесь. Для выполнения открой компилятор кнопкой сверху.'}</div><iframe id="preview" title="Предпросмотр HTML" sandbox="" hidden></iframe></div>${native?'':`<div class="external-runtime" id="external-runtime" hidden><div class="editor-bar"><span>OneCompiler / ${esc(course.name)}</span><button class="button secondary small" id="send-code">Передать черновик</button></div><p class="muted runtime-status" id="runtime-status">Загружаем среду. Выполнение происходит на стороне OneCompiler.</p><iframe id="compiler" title="Компилятор ${esc(course.name)} OneCompiler" referrerpolicy="no-referrer" allow="clipboard-write" sandbox="allow-scripts allow-same-origin allow-forms allow-downloads" hidden></iframe><a class="runtime-fallback" target="_blank" rel="noopener noreferrer" href="https://onecompiler.com/${COMPILER_LANGUAGE[course.id]}">Если среда не загрузилась, открыть отдельно ↗</a></div>`}<div class="lesson-bottom"><button class="button secondary small" id="reset">Вернуть пример</button><button class="button secondary small" id="check">${native?'Проверить задание':'Отметить как изученное'}</button></div><p class="muted" id="save-status" aria-live="polite">Черновик сохраняется на этом устройстве. ${native?'Ctrl / ⌘ + Enter: запуск.':'При передаче черновика код получает OneCompiler.'}</p></section></div><a class="lesson-helper-link" href="${url('assistant',course.id)}">Непонятно? Открой чат с помощником ↗</a><div class="lesson-navigation">${lesson>0?`<a href="${url('learn',course.id,lesson-1)}">← Предыдущая тема</a>`:'<span>Начало маршрута</span>'}${lesson<5?`<a class="button" href="${url('learn',course.id,lesson+1)}">Следующая тема →</a>`:`<a class="button" href="${url('profile')}">Мой прогресс →</a>`}</div></div>`}

let runner=null,runTimer;function bindLearn(){const key='code-'+course.id+'-'+lesson;let result=[],ran=false;$('#code').oninput=()=>{stop();result=[];store.set(key,$('#code').value);ran=false;$('#save-status').textContent='Код изменён. Для проверки запусти его заново.'};$('#code').onkeydown=e=>{if(e.key==='Tab'){e.preventDefault();const el=e.target,s=el.selectionStart;el.setRangeText('  ',s,el.selectionEnd,'end');el.dispatchEvent(new Event('input'))}if((e.ctrlKey||e.metaKey)&&e.key==='Enter'){e.preventDefault();$('#run').click()}};const stop=()=>{if(runner)runner.terminate();runner=null;clearTimeout(runTimer);$('#run').disabled=false};$('#run').onclick=()=>{store.set(key,$('#code').value);ran=false;result=[];$('#preview').hidden=true;if(course.id==='html'){$('#preview').hidden=false;$('#preview').srcdoc=$('#code').value;$('#output').textContent='Предпросмотр обновлён. Скрипты внутри HTML не выполняются.';ran=true;return}if(course.id!=='javascript'){openCompiler();return}stop();$('#output').textContent='Выполняется…';$('#run').disabled=true;const workerCode=`const display=v=>{if(typeof v==='string')return v;try{return JSON.stringify(v)??String(v)}catch{return String(v)}};self.onmessage=async e=>{let lines=0;const send=(kind,text)=>{if(kind==='log'&&++lines>100)return;self.postMessage({kind,text:String(text).slice(0,2000)})};const console={log:(...a)=>send('log',a.map(display).join(' ')),warn:(...a)=>send('log',a.map(display).join(' ')),error:(...a)=>send('log',a.map(display).join(' '))};try{await new Function('console','return (async()=>{'+e.data+'\\n})()')(console);send('done','')}catch(e){send('error',e.name+': '+e.message)}}`;const blobURL=URL.createObjectURL(new Blob([workerCode],{type:'application/javascript'}));try{runner=new Worker(blobURL)}catch(error){URL.revokeObjectURL(blobURL);stop();$('#output').textContent='Браузер не разрешил запустить среду: '+error.message;return}URL.revokeObjectURL(blobURL);const activeRunner=runner;runner.onmessage=e=>{if(runner!==activeRunner)return;if(e.data.kind==='log'){if(result.length<100)result.push(String(e.data.text).slice(0,2000));$('#output').textContent=result.join('\n')}else if(e.data.kind==='error'){$('#output').textContent='Ошибка: '+e.data.text;stop()}else{ran=true;$('#output').textContent=result.join('\n')||'Код выполнен без вывода.';stop()}};runner.onerror=e=>{if(runner!==activeRunner)return;e.preventDefault();$('#output').textContent='Не удалось выполнить код: '+e.message;stop()};runTimer=setTimeout(()=>{$('#output').textContent='Выполнение остановлено: превышен лимит 3 секунды. Проверь циклы.';stop()},3000);runner.postMessage($('#code').value)};$('#reset').onclick=()=>{stop();result=[];$('#code').value=sample();store.set(key,sample());ran=false;$('#output').textContent='Исходный пример восстановлен.';$('#preview').hidden=true};$('#check').onclick=()=>{if(course.id==='javascript'&&!ran){toast('Сначала запусти код без ошибок');return}if(course.id==='javascript'){const expected=[['Я учусь программировать'],['1','2','3'],['7'],['3'],['Нажатие обработано'],['Готово']][lesson];if(result.join('\n')!==expected.join('\n')){toast('Результат пока не совпадает с заданием. Проверь условие.');return}}if(course.id==='html'){const error=checkHTML($('#code').value,lesson);if(error){toast(error);return}}const done=store.get('done',{});done[course.id+'-'+lesson]=true;const enrolled=store.get('enrolled',[]);if(!enrolled.includes(course.id))enrolled.push(course.id);const completions=store.get('course-completions',{}),finished=course.topics.every((_,i)=>done[course.id+'-'+i]===true);if(finished&&!completions[course.id])completions[course.id]=Date.now();if(!store.batch([['done',done],['enrolled',enrolled],['course-completions',completions]]))return;document.querySelectorAll('.lesson-list a').forEach((a,i)=>{if(i===lesson)a.querySelector('b').textContent='✓'});toast(['javascript','html'].includes(course.id)?'Задание выполнено. Прогресс сохранён.':'Тема отмечена как изученная');$('#save-status').textContent=finished?'✓ Все темы завершены. Направление добавлено в достижения профиля.':'✓ Тема завершена. Можно переходить дальше.'};const video=store.get('videos',{})[course.id+'-'+lesson];if(video)mountLessonVideo(video)}

function initials(n){const a=n.trim().split(/\s+/);return a.length?`${a[0]}${a[1]?' '+a[1][0]+'.':''}${a[2]?a[2][0]+'.':''}`:'Мой профиль'}
function profilePage(){const account=window.SchoolAccount,state=account?.state;if(state?.enabled&&(!state.ready||!state.user||state.error||state.recovery))return account.panel();const p=store.get('profile',{name:'',about:''}),enrolled=store.get('enrolled',[]).filter(id=>!completedCourses().some(c=>c.id===id&&!c.demo)),done=store.get('done',{});return `<div class="container page profile-page"><a class="crumb" href="index.html">← Главная</a><h1 class="page-title">Личный кабинет</h1><div class="notice">${state?.enabled?'Тестовый аккаунт Supabase. Имя, информация о себе и аватар сохраняются в облаке. Прогресс и проекты пока хранятся на этом устройстве.':'Локальный профиль на этом устройстве. Это пока не аккаунт: вход с другого устройства и общий список пользователей появятся после подключения сервера.'}</div>${state?.enabled?`<div class="account-toolbar"><span>${esc(state.user.email||'')}</span><button class="button secondary small" id="account-signout" type="button">Выйти</button></div>`:''}<div class="split profile-layout"><form id="profile-form" class="panel stack profile-form"><div class="profile-top">${p.avatar?`<img class="avatar" src="${esc(p.avatar)}" alt="Моя аватарка">`:'<div class="avatar">[ / ]</div>'}<div><h2>${p.name?esc(initials(p.name)):'Твой профиль'}</h2><span class="muted">Показываем фамилию и инициалы</span></div></div><label>Фамилия, имя, отчество<input id="full-name" value="${esc(p.name)}" maxlength="100" autocomplete="name" placeholder="Введи своё ФИО" required></label><label>О себе, по желанию<textarea id="about" maxlength="1000" placeholder="Что изучаешь и какие проекты хочешь создавать">${esc(p.about)}</textarea></label><label>Аватарка, JPG / PNG / WebP до 3 МБ<input id="avatar-file" type="file" accept="image/jpeg,image/png,image/webp"></label>${state?.enabled?'<button class="text-button" id="import-device-profile" type="button">Подставить старый профиль с этого устройства</button>':''}<div class="profile-form-actions"><button class="button" type="submit">Сохранить профиль</button><button class="button secondary" id="remove-avatar" type="button">Убрать фото</button></div></form><div class="panel profile-learning"><div class="cabinet-shortcuts"><a href="${url('daily')}">Задание дня ↗</a><a href="${url('portfolio')}">Моё портфолио ↗</a><a href="${url('assistant')}">Помощник ↗</a><a href="${url('messages')}">Люди и сообщения ↗</a></div><a class="text-link profile-preview-link" href="${url('member')}">Посмотреть мой профиль ↗</a>${completedSection()}<h3>Сейчас изучаю</h3>${enrolled.length?enrolled.map(id=>{const c=courses.find(x=>x.id===id);if(!c)return '';const n=c.topics.filter((_,i)=>done[id+'-'+i]).length;return `<article class="module"><h3>${esc(c.name)}</h3><span class="muted">Изучено тем: ${n} из ${c.topics.length}</span><div class="progress"><i style="width:${n/c.topics.length*100}%"></i></div><a class="button secondary small" href="${url('learn',id,c.topics.findIndex((_,i)=>!done[id+'-'+i])<0?0:c.topics.findIndex((_,i)=>!done[id+'-'+i]))}">Продолжить →</a></article>`}).join(''):'<p class="muted">Сейчас нет незавершённых направлений. Можно выбрать следующее.</p><a class="button secondary" href="'+url('catalog')+'">Выбрать направление ↗</a>'}<p class="muted">Пройденных тем всего: ${Object.keys(done).length}</p></div></div></div>`}
function bindProfile(){const account=window.SchoolAccount;account?.bind();if(!$('#profile-form'))return;let avatar=store.get('profile',{}).avatar||'';if($('#import-device-profile'))$('#import-device-profile').onclick=()=>{try{const p=normalizeStored('profile',JSON.parse(localStorage.getItem('school-profile')),{name:'',about:'',avatar:''});if(!p.name&&!p.avatar){toast('На этом устройстве нет старого профиля.');return;}$('#full-name').value=p.name;$('#about').value=p.about;avatar=p.avatar;toast('Данные подставлены. Проверь и нажми «Сохранить профиль».');}catch{toast('Не удалось прочитать старый профиль.');}};$('#avatar-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;if(file.size>3*1024*1024){toast('Выбери изображение до 3 МБ');e.target.value='';return}if(!['image/jpeg','image/png','image/webp'].includes(file.type)){toast('Нужен JPG, PNG или WebP');return}try{const bitmap=await createImageBitmap(file),canvas=document.createElement('canvas');canvas.width=canvas.height=256;const size=Math.min(bitmap.width,bitmap.height);canvas.getContext('2d').drawImage(bitmap,(bitmap.width-size)/2,(bitmap.height-size)/2,size,size,0,0,256,256);avatar=canvas.toDataURL('image/jpeg',.85);bitmap.close();if(avatar.length>160000){avatar=store.get('profile',{}).avatar||'';toast('Фото слишком сложное. Выбери другое изображение.');return;}toast('Фото выбрано. Сохрани профиль.')}catch{toast('Не удалось прочитать изображение')}};$('#remove-avatar').onclick=()=>{avatar='';$('#avatar-file').value='';toast('Аватарка будет убрана после сохранения')};$('#profile-form').onsubmit=async e=>{e.preventDefault();const name=$('#full-name').value.trim();if(name.split(/\s+/).length<2){toast('Укажи хотя бы фамилию и имя');return}const profile={name,about:$('#about').value.trim(),avatar};if(account?.state.enabled){const button=e.submitter||$('#profile-form button[type=submit]');button.disabled=true;try{await account.saveProfile(profile);toast('Профиль сохранён в облаке');renderPage();}catch(error){toast(account.errorMessage(error));button.disabled=false;}}else if(store.set('profile',profile)){location.href=url('profile')}}}
function messagesPage(){return `<div class="container page"><a class="crumb" href="${url('profile')}">← В кабинет</a><h1 class="page-title">Сообщения</h1><div class="notice">Предпросмотр интерфейса чата. Сейчас доступен только диалог «Избранное» для собственных заметок. Доставки сообщений другим людям пока нет.</div><div class="chat-layout"><aside class="dialogs"><h3>Твои диалоги</h3><a class="assistant-dialog" href="${url('assistant')}"><b>[ ? ]</b><span>Помощник<small>Отдельный чат по обучению</small></span><span>↗</span></a>${peopleSearchUI()}<label class="notes-search">Поиск в избранном<input type="search" id="chat-search" placeholder="Поиск в заметках" aria-label="Поиск в заметках"></label><div class="dialog-item">▧ &nbsp; Избранное</div><p class="muted">После подключения сервера здесь появятся ученики и преподаватель.</p></aside><section class="chat"><div class="chat-head">Избранное <span class="muted"> / Личные заметки</span></div><div id="messages" class="messages" aria-live="polite"></div><form class="chat-compose" id="message-form"><input id="message" aria-label="Текст заметки" placeholder="Ссылка, идея или вопрос на потом…" maxlength="4000" required><button class="button" type="submit">Сохранить ↑</button></form></section></div></div>`}
function bindMessages(){const render=()=>{const term=$('#chat-search').value.toLowerCase();const notes=store.get('notes',[]).filter(n=>n.text.toLowerCase().includes(term));$('#messages').innerHTML=notes.length?notes.map(n=>`<div class="bubble">${esc(n.text)}<small>${esc(new Date(n.time).toLocaleTimeString('ru',{hour:'2-digit',minute:'2-digit'}))} · на устройстве</small></div>`).join(''):'<p class="muted">Здесь можно сохранить свои заметки к урокам.</p>';$('#messages').scrollTop=$('#messages').scrollHeight};$('#chat-search').oninput=render;$('#message-form').onsubmit=e=>{e.preventDefault();const text=$('#message').value.trim();if(!text)return;const notes=store.get('notes',[]);notes.push({text,time:Date.now()});if(store.set('notes',notes)){$('#message').value='';render()}};render()}
function adminPage(){return `<div class="container page"><a class="crumb" href="index.html">← Главная</a><h1 class="page-title">Мастерская преподавателя</h1><div class="notice">Локальный редактор предварительной версии. Изменения видны только в этом браузере. Это не защищённая админка. Управление учениками и публикация материалов появятся после подключения сервера.</div><div class="split"><form id="course-form" class="panel stack"><h3>Настройки направления</h3><label>Направление<select id="admin-course">${courses.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></label><label>Описание<textarea id="course-description" maxlength="500" required></textarea></label><label>Темы, по одной на строке. Всего 6<textarea id="course-topics" rows="7" required></textarea></label><button class="button" type="submit">Сохранить изменения</button></form><div class="stack"><form id="video-form" class="panel stack"><h3>Видео для урока</h3><label>Урок<select id="video-lesson"></select></label><label>Ссылка на YouTube или файл MP4 / WebM<input id="video-url" type="url" placeholder="https://www.youtube.com/watch?v=…"></label><p class="muted">Вставь ссылку YouTube, youtu.be или на MP4/WebM. Видео откроется внутри урока рядом с кодом. Для YouTube владелец ролика должен разрешить встраивание. Пустое поле убирает видео.</p><button class="button secondary">Сохранить видео</button><a class="button secondary" id="admin-preview" href="${url('learn','javascript')}">Посмотреть урок ↗</a></form><div class="panel stack"><h3>Резервная копия материалов</h3><p class="muted">Экспорт включает описания, темы и ссылки на видео. Профиль и личные заметки в него не попадают.</p><button class="button secondary" id="export">Скачать JSON</button><label>Восстановить материалы<input type="file" accept="application/json,.json" id="import"></label></div></div></div></div>`}
function bindAdmin(){if(query.get('course'))$('#admin-course').value=course.id;const selected=()=>courses.find(c=>c.id===$('#admin-course').value);const fillVideo=()=>{const id=$('#admin-course').value+'-'+$('#video-lesson').value;$('#video-url').value=store.get('videos',{})[id]||'';$('#admin-preview').href=url('learn',selected().id,+$('#video-lesson').value)};const fill=()=>{const c=selected();$('#course-description').value=c.description;$('#course-topics').value=c.topics.join('\n');$('#video-lesson').innerHTML=c.topics.map((t,i)=>`<option value="${i}">${i+1}. ${esc(t)}</option>`).join('');fillVideo()};$('#admin-course').onchange=fill;$('#video-lesson').onchange=fillVideo;fill();if(query.has('lesson')){$('#video-lesson').value=lesson;fillVideo()};$('#course-form').onsubmit=e=>{e.preventDefault();const topics=$('#course-topics').value.split('\n').map(x=>x.trim()).filter(Boolean);if(topics.length!==6){toast('Нужно ровно 6 тем, каждая на отдельной строке');return}const c=selected(),description=$('#course-description').value.trim();if(!description||description.length>500||topics.some(t=>t.length>150)){toast('Нужно описание до 500 символов и темы до 150 символов');return}const all=store.get('courses',{});all[c.id]={description,topics};if(!store.set('courses',all))return;c.description=description;c.topics=topics;fill();toast('Материалы сохранены локально')};$('#video-form').onsubmit=e=>{e.preventDefault();const value=$('#video-url').value.trim();if(value&&!validVideo(value)){toast('Нужна ссылка YouTube или HTTPS-ссылка на MP4/WebM');return}const videos=store.get('videos',{}),key=selected().id+'-'+$('#video-lesson').value;if(value)videos[key]=value;else delete videos[key];if(store.set('videos',videos))toast('Настройки видео сохранены')};$('#export').onclick=()=>{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify({schema:1,courses:store.get('courses',{}),videos:store.get('videos',{})},null,2)],{type:'application/json'}));a.download='school-materials.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};$('#import').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>1000000)throw Error();const data=JSON.parse(await file.text());if(!data||data.schema!==1||!data.courses||typeof data.courses!=='object'||Array.isArray(data.courses)||!data.videos||typeof data.videos!=='object'||Array.isArray(data.videos))throw Error();const clean={};for(const [id,c] of Object.entries(data.courses)){if(!courses.some(x=>x.id===id)||typeof c.description!=='string'||!c.description.trim()||c.description.length>500||!Array.isArray(c.topics)||c.topics.length!==6||c.topics.some(t=>typeof t!=='string'||!t.trim()||t.length>150))throw Error();clean[id]={description:c.description,topics:c.topics}}const videos={};for(const [id,v]of Object.entries(data.videos)){if(!courses.some(c=>Array.from({length:6},(_,i)=>c.id+'-'+i).includes(id))||typeof v!=='string'||!validVideo(v))throw Error();videos[id]=v}if(!store.batch([['courses',clean],['videos',videos]]))return;location.reload()}catch{toast('Файл не подходит. Выбери экспорт материалов этого сайта.')}}}
const pages={home,member:memberPage,daily:dailyPage,portfolio:portfolioPage,assistant:assistantPage,roadmap:roadmapPage,projects:projectsPage,help:helpPage,course:coursePage,learn:learnPage,profile:profilePage,messages:messagesPage,admin:adminPage,catalog:()=>`<div class="container page"><a class="crumb" href="index.html">← Главная</a>${catalog()}<div class="notice">Каталог знакомит с направлениями программирования. Наличие авторского курса по каждому языку уточняется у преподавателя.</div></div>`};function renderPage(){const storageNotice=$('#storage-notice');if(storageNotice&&window.SchoolAccount?.state.enabled)storageNotice.textContent='Тестовая версия. Профиль сохраняется в облаке после входа, учебный прогресс пока на устройстве.';document.documentElement.dataset.view=view;if(view==='profile'&&query.get('demo')==='achievements')store.set('demo-achievements',true);document.querySelectorAll('.mobile-dock a').forEach(a=>{if(new URL(a.href,location.href).searchParams.get('view')===view)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});$('#main').innerHTML=(pages[view]||home)();document.title=({member:'Профиль ученика',daily:'Задание дня',portfolio:'Моё портфолио',assistant:'Помощник',roadmap:'Как учиться',projects:'Учебные проекты',help:'Помощь',course:course.name,learn:course.topics[lesson],profile:'Личный кабинет',messages:'Сообщения',admin:'Мастерская преподавателя',catalog:'Каталог направлений'}[view]||'Школа программирования')+' | Школа программирования';
if(['home','catalog'].includes(view)){bindCatalog();const sculpture=$('.sculpture');if(sculpture&&matchMedia('(hover:hover) and (prefers-reduced-motion:no-preference)').matches){sculpture.onpointermove=e=>{const r=sculpture.getBoundingClientRect();$('.solid').style.transform=`rotateX(${12-(e.clientY-r.top-r.height/2)/25}deg) rotateY(${-23+(e.clientX-r.left-r.width/2)/25}deg) rotateZ(-8deg)`};sculpture.onpointerleave=()=>$('.solid').style.transform=''}}
if(view==='course')$('#enroll').onclick=()=>{let list=store.get('enrolled',[]);const exists=list.includes(course.id);list=exists?list.filter(x=>x!==course.id):[...list,course.id];if(!store.set('enrolled',list))return;$('#enroll').textContent=exists?'Добавить в мои направления':'Убрать из моих направлений';$('#enroll-status').textContent=exists?'Направление убрано из кабинета':'Добавлено в личный кабинет'};
if(view==='daily')bindDaily();if(view==='portfolio')bindPortfolio();if(view==='assistant')bindAssistant();if(view==='learn'){bindLearn();bindWorkspace()};if(view==='profile')bindProfile();if(['profile','member'].includes(view))bindCompletionDisclosure();if(['profile','member'].includes(view)&&$('#hide-demo-achievements'))$('#hide-demo-achievements').onclick=()=>{if(store.set('demo-achievements',false)){query.delete('demo');const target=new URL(location.href);target.searchParams.delete('demo');history.replaceState(null,'',target.href);renderPage()}};if(view==='messages'){bindMessages();bindPeople()};if(view==='admin')bindAdmin();

}
renderPage();

function faqItems(items){return items.map(([q,a])=>`<details class="faq-item"><summary>${q}<span>+</span></summary><p>${a}</p></details>`).join('')}
function pathwaysSection(){return `<section class="block"><h2>Не знаешь, с чего начать?</h2><p class="lead">Выбирай по тому, что хочется создавать. Одного языка для первого шага достаточно.</p><div class="pathway-grid">${[['web','Интерфейсы и сайты','HTML/CSS → JavaScript → TypeScript','html'],['data','Данные и автоматизация','Python → SQL → работа с данными','python'],['backend','Логика приложений','Python, Java, Go или C# → API','java'],['mobile','Мобильная разработка','Kotlin, Swift или Dart → приложение','kotlin']].map(([g,t,p,id])=>`<a href="${url('course',id)}" class="pathway"><span class="tag">${groupNames[g]}</span><h3>${t}</h3><p>${p}</p><span class="pathway-arrow">↗</span></a>`).join('')}</div><a class="text-link" href="${url('roadmap')}">Разобраться в маршруте обучения →</a></section>`}
function projectSection(){return `<section class="block"><h2>Пиши код с понятной целью</h2><p class="lead">Небольшой законченный проект помогает соединить отдельные темы. Вот несколько идей для самостоятельной практики.</p><div class="project-grid">${[['web','01','Каталог с поиском','Покажи список, добавь фильтры и сохрани выбор пользователя.','JS / HTML / CSS'],['data','02','Отчёт по данным','Очисти таблицу, посчитай показатели и объясни результаты.','PYTHON / SQL'],['systems','03','Заметки в терминале','Добавление, поиск и хранение записей в одной программе.','C++ / RUST / GO']].map(([g,n,t,d,tech])=>`<a href="${url('projects')}#${g}" class="project-tile"><div class="project-diagram" aria-hidden="true"><span>${n}</span><b>${g==='web'?'[ search ]':g==='data'?'Σ / data':'$ notes'}</b></div><span class="tag">${tech}</span><h3>${t}</h3><p>${d}</p><span class="text-link">Разобрать задачу ↗</span></a>`).join('')}</div></section>`}
function homeFaq(){return `<section class="block faq-section"><h2>Вопросы, которые возникают в начале</h2>${faqItems([['Можно ли заниматься с телефона?','Да. Материал, видео и короткие примеры доступны на узком экране. Панели материала и кода переключаются вкладками. Большие программы удобнее писать на компьютере.'],['Нужно ли регистрироваться, чтобы попробовать?','Для открытой мастерской регистрация не нужна. Черновики, профиль и прогресс пока хранятся в браузере на этом устройстве.'],['Где появятся видео преподавателя?','У каждой темы есть вкладка «Видеоурок». Преподаватель сможет добавить туда материал через мастерскую.'],['Можно ли запускать разные языки?','JavaScript и HTML работают локально. Для других направлений доступна встроенная внешняя среда OneCompiler с запуском на её стороне. Для неё нужен интернет.']])}<a class="text-link" href="${url('help')}">Открыть помощь →</a></section>`}
function roadmapPage(){return `<div class="container page"><a class="crumb" href="index.html">← Главная</a><h1 class="page-title">Обучение с понятным маршрутом.</h1><p class="lead">Сначала основа, затем небольшая задача и собственный проект. Темп можно выбирать по своему расписанию.</p>${pathwaysSection()}<section class="block learning-tools"><h2>Практика становится привычкой</h2><p class="lead">Сохраняй свои решения, собирай работы и возвращайся к вопросам, которые хочется разобрать.</p><div class="learning-tool-grid"><a href="${url('daily')}"><span class="tag">ПРАКТИКА</span><h3>Задание дня</h3><p>Небольшая задача с проверкой вывода и историей решённых дней.</p><span>Попробовать →</span></a><a href="${url('portfolio')}"><span class="tag">РЕЗУЛЬТАТ</span><h3>Моё портфолио</h3><p>Работы, скриншоты и технологии. Собирай результат обучения в одном месте.</p><span>Добавить работу →</span></a><a href="${url('assistant')}"><span class="tag">ПОДДЕРЖКА</span><h3>Помощник</h3><p>Отдельный чат для вопросов по коду. Подключение ИИ готовится.</p><span>Открыть чат →</span></a></div></section><section class="block approach"><div><h2>Одна тема.<br>Один следующий шаг.</h2><p class="lead">Не нужно одновременно изучать весь каталог. Выбери направление и постепенно усложняй задачи.</p></div><div class="steps">${[['1','Разбери пример','Прочитай объяснение. Назови своими словами, какие данные получает программа и какой результат должна вернуть.'],['2','Измени условие','Поменяй значения или добавь небольшой шаг. Предскажи результат до запуска.'],['3','Проверь края','Что будет с пустым списком, нулём или неправильным вводом? Ошибка тоже помогает понять поведение.'],['4','Собери самостоятельное решение','Закрой пример и повтори идею в своей задаче. Запиши вопросы в заметках урока.']].map(([n,t,d])=>`<article><b>${n}</b><div><h3>${t}</h3><p>${d}</p></div></article>`).join('')}</div></section><section class="block"><h2>Что нужно подготовить</h2><div class="skill-grid">${[['Браузер и клавиатура','Для начала подойдёт современный браузер. Клавиатура заметно удобнее для кода, но короткие примеры можно менять и с телефона.'],['Время на практику','Выдели спокойное время, когда можно разобрать одну тему. Возвращайся к сложным местам и не пропускай практику.'],['Место для вопросов','Записывай не только ошибку, но и ожидаемый результат. Такой вопрос гораздо проще разобрать с преподавателем.'],['Свой небольшой проект','Выбери понятную задачу из своей жизни. Личный интерес помогает увидеть смысл в изучении синтаксиса.']].map(([t,d])=>`<article><h3>${t}</h3><p>${d}</p></article>`).join('')}</div></section></div>`}
function projectsPage(){return `<div class="container page"><a class="crumb" href="index.html">← Главная</a><h1 class="page-title">От упражнения<br>к своему проекту.</h1><p class="lead">Идеи самостоятельной практики. Это примеры задач, а не работы учеников и не подтверждённая программа преподавателя.</p>${['web','data','systems','backend','mobile'].map((group,i)=>{const g=LEARNING[group];return `<section class="block project-detail" id="${group}"><div class="project-number">${String(i+1).padStart(2,'0')}</div><div><span class="tag">${groupNames[group]}</span><h2>${g.project}</h2><p class="lead">${g.projectText}</p><h3>Минимальная версия</h3><p class="muted">Опиши исходные данные и результат. Реализуй одно основное действие, затем добавь просмотр и обработку ошибок.</p><h3>Как усложнить</h3><p class="muted">Добавь поиск, сохранение данных и проверки нестандартных случаев. Напиши короткое описание: что программа умеет и как её запустить.</p><div class="project-checks"><span>✓ Понятная задача</span><span>✓ Работающий пример</span><span>✓ Проверка ошибок</span><span>✓ Описание решения</span></div><a class="button secondary" href="${url('course',courses.find(c=>c.group===group).id)}">Выбрать язык для проекта ↗</a></div></section>`}).join('')}</div>`}
function helpPage(){return `<div class="container page help-page"><a class="crumb" href="index.html">← Главная</a><h1 class="page-title">Меньше препятствий.<br>Больше практики.</h1><p class="lead">Ответы о редакторе, сохранении данных и доступных возможностях платформы.</p>${faqItems([['Редактор и консоль: в чём разница?','В редакторе пишут исходный код. Консоль показывает вывод программы и ошибки. Для консольного ввода в среде OneCompiler есть поле STDIN.'],['Почему языкам нужны разные движки?','Браузер исполняет JavaScript. Для Java, Python, C++ и других языков нужен компилятор или интерпретатор. Внешняя среда предоставляет его без установки на твой компьютер.'],['Куда отправляется мой код?','Локальные примеры JavaScript и HTML остаются на устройстве. При передаче черновика во внешний компилятор код получает OneCompiler. Не вставляй туда пароли и личные данные.'],['Что делать, если внешняя среда не открывается?','Проверь интернет и попробуй ссылку «Открыть отдельно» под компилятором. Доступность сервиса зависит от сети. Черновик в редакторе сайта остаётся сохранённым.'],['Как сохранить работу?','Изменения кода и заметки сохраняются автоматически в браузере. Очистка данных браузера удалит их. Скопируй важный код в отдельный файл.'],['Почему профиль не виден на другом устройстве?','Сервер пока не подключён. Профиль, заметки и прогресс существуют только в текущем браузере. Общие аккаунты и доставка сообщений появятся на следующем этапе.'],['Как добавить видео?','Открой урок, затем вкладку «Видеоурок» и кнопку «Добавить видео». В мастерской укажи ссылку на YouTube или HTTPS-файл MP4/WebM.'],['Где программа, стоимость и контакты преподавателя?','Пока преподаватель не предоставил эти данные. На сайте размещены обзорные направления и открытые учебные примеры.']])}<div class="notice">Если задаёшь вопрос по коду, приложи условие, свой пример, ожидаемый результат и полный текст ошибки. Это поможет быстрее разобраться.</div></div>`}
function openCompiler(){const box=$('#external-runtime'),frame=$('#compiler');box.hidden=false;if(!frame.src){const theme=document.documentElement.dataset.theme;frame.src='https://onecompiler.com/embed/'+COMPILER_LANGUAGE[course.id]+'?hideLanguageSelection=true&hideNew=true&hideTitle=true&listenToEvents=true&theme='+theme;frame.hidden=false;frame.onload=()=>{if($('#runtime-status'))$('#runtime-status').textContent='Страница среды открыта. Если редактор виден, нажми «Передать черновик», затем Run. Если нет, используй ссылку ниже.'};}$('#output').textContent='Среда выполнения открыта ниже редактора. Передай черновик и запусти его кнопкой Run.';box.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'auto':'smooth',block:'nearest'})}
function bindWorkspace(){const activate=(selector,b)=>{document.querySelectorAll(selector).forEach(x=>x.setAttribute('aria-selected',String(x===b)))};document.querySelectorAll('[data-workspace]').forEach(b=>b.onclick=()=>{$('.workspace').dataset.panel=b.dataset.workspace;activate('[data-workspace]',b)});document.querySelectorAll('[data-material]').forEach(b=>b.onclick=()=>{activate('[data-material]',b);['theory','video','notes'].forEach(id=>$('#'+id+'-panel').hidden=id!==b.dataset.material)});$('#lesson-note').oninput=()=>{if(store.set('lesson-note-'+course.id+'-'+lesson,$('#lesson-note').value))$('#note-status').textContent='Заметка сохранена.'};$('#clear-output').onclick=()=>{$('#output').textContent='Вывод очищен.'};if($('#send-code'))$('#send-code').onclick=()=>{const frame=$('#compiler');if(!frame.src){openCompiler();return}const ext={python:'py',java:'java',cpp:'cpp',csharp:'cs',typescript:'ts',go:'go',sql:'sql',rust:'rs',php:'php',kotlin:'kt',swift:'swift',dart:'dart',c:'c',ruby:'rb',r:'r',scala:'scala',lua:'lua',bash:'sh'}[course.id];frame.contentWindow.postMessage({eventType:'populateCode',language:COMPILER_LANGUAGE[course.id],files:[{name:course.id==='java'?'Main.java':'main.'+ext,content:$('#code').value}]},'https://onecompiler.com');$('#runtime-status').textContent='Запрос на передачу отправлен. Проверь код в редакторе OneCompiler, затем нажми Run.'};}
// Native transitions preserve browser history, focus and the Back button.

let navigationId=0;
function updateRoute(){stopFeatures();query=new URLSearchParams(location.search);view=query.get('view')||'home';course=courses.find(c=>c.id===query.get('course'))||courses[0];lesson=Math.max(0,Math.min(5,parseInt(query.get('lesson'))||0));if(runner){runner.terminate();runner=null}clearTimeout(runTimer);renderPage();$('#course-menu').open=false;const target=location.hash?document.getElementById(safeHash(location.hash)):null;if(target)target.scrollIntoView({block:'start'});else scrollTo(0,0);$('#main').focus({preventScroll:true});}
function routeTo(target,push=true){const id=++navigationId,main=$('#main'),reduce=matchMedia('(prefers-reduced-motion:reduce)').matches;const finish=()=>{if(id!==navigationId)return;if(push)history.pushState(null,'',target.href);updateRoute();if(!reduce&&main.animate)main.animate([{opacity:0,transform:'translateY(6px)'},{opacity:1,transform:'translateY(0)'}],{duration:220,easing:'cubic-bezier(.23,1,.32,1)'});};if(!reduce&&main.animate){main.animate([{opacity:1},{opacity:0}],{duration:110,easing:'ease-out'}).finished.then(finish,finish)}else finish()}
document.addEventListener('click',event=>{const a=event.target.closest('a[href]');if(!a||event.defaultPrevented||event.button!==0||event.metaKey||event.ctrlKey||event.shiftKey||event.altKey||a.target||a.hasAttribute('download'))return;const target=new URL(a.href,location.href);if(target.origin!==location.origin||target.pathname!==location.pathname||!target.pathname.endsWith('index.html'))return;if(target.search===location.search&&target.hash)return;event.preventDefault();routeTo(target)});
window.addEventListener('popstate',()=>{navigationId++;updateRoute()});

function safeHash(hash){try{return decodeURIComponent(hash.slice(1))}catch{return ''}}
function checkHTML(source,index){const doc=new DOMParser().parseFromString(source,'text/html');if(![...doc.querySelectorAll('h1')].some(el=>el.textContent.trim()==='Я учусь программировать'))return 'Добавь h1 с текстом из задания';const css=[...doc.querySelectorAll('style')].map(el=>el.textContent).join('\n').replace(/\/\*[\s\S]*?\*\//g,'');if(index===1&&!doc.querySelector('main h1'))return 'Помести главный заголовок внутрь main';if(index===2&&!/[^{}]*h1[^{}]*\{[^}]*\bcolor\s*:\s*[^;}]+/i.test(css))return 'Добавь CSS-правило с цветом заголовка';if(index===3&&!/display\s*:\s*(inline-)?flex\b/i.test(css))return 'Добавь Flexbox через display: flex';if(index===4&&!/display\s*:\s*(inline-)?grid\b/i.test(css))return 'Добавь сетку через display: grid';if(index===5&&!/@media[^{}]*max-width\s*:\s*600px/i.test(css))return 'Добавь медиазапрос для экрана до 600px';return ''}

window.addEventListener('school-account-change',()=>{renderPage();});
